UPDATE tb_bbs_comment
   SET like_count = #{likeCount}
 WHERE comment_id = #{commentId}
   AND delete_yn  = 'N'

UPDATE tb_bbs_comment
   SET report_count = #{reportCount}
 WHERE comment_id = #{commentId}
   AND delete_yn  = 'N'

mapper.delete:
DELETE FROM tb_bbs_comment
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}
